CREATE   VIEW [FO].[vwPurchaseOrderPostedTransactions]
AS
SELECT 
	vij.[PURCHID] AS [Purchase Order No]
	,vij.[ORDERACCOUNT] AS [Order Account]

--	,vij.[CASHDISCCODE]
--	,vij.[CASHDISC]
--	,vij.[CASHDISCPERCENT]
	,vij.[CURRENCYCODE]
	,vij.[DEFAULTDIMENSION]
	,CAST(vij.[DOCUMENTDATE] AS DATE) AS [Document Date]
	,vij.[DOCUMENTNUM] AS [Document Number]
	,CAST(vij.[DUEDATE] AS date) AS [Due Date]
	,vij.[EXCHRATE] AS [Exchange Rate]
	,vij.[INTERNALINVOICEID]
	,vij.[INVOICEACCOUNT] AS [Invoice Account]
	,vij.[INVOICEAMOUNT] AS [Invoice Amount]
	,vij.[INVOICEAMOUNTMST] AS [Invoice Amount MST]
	,CAST(vij.[INVOICEDATE] AS date) AS [Invoice Date]
	,vij.[INVOICEID] AS [Invoice Id]
	,vij.[LEDGERVOUCHER]
--	,vij.[NUMBERSEQUENCEGROUP]
	,vij.[PAYMENT]
	,vij.[POSTINGPROFILE]
	,vij.[SALESBALANCE] AS [Sales Balance]
	,vij.[QTY] AS [Quantity]
	,vij.[SUMTAX] AS [Sum Tax]
	,vij.[SUMLINEDISC]
	,vij.[SUMMARKUP]
	,vij.[SUMMARKUPMST]
	,vij.[TAXGROUP]
	,vij.[VENDGROUP]
	,vij.[DATAAREAID]
	,vij.[VENDGROUP] + '_' + vij.[DATAAREAID] AS [VendGroup_Key]
	,vij.[RECID]
	,vij.[PARTITION]
	,vij.[CREATEDDATETIME]
	,vij.[CREATEDBY]
	,vij.[MODIFIEDDATETIME]
	,vit.[LEDGERDIMENSION]
	,vit.[LINEAMOUNT]
	,vit.[LINEAMOUNTMST]
	,vit.[TAXAMOUNT] AS [LINEAMOUNTTAX]
	,vit.[LINENUM]
	,vit.[LINEPERCENT]
	,vit.[NAME] AS [Line Description]
	,vit.[inventtransid]
	,vit.[ITEMID]
	--,vij.[PURCHASETYPE]
	,'N/A' AS [Cost Center Code]
	,'N/A' AS [Paymterm_Key]
	,pt.[WORKERPURCHPLACER] AS [Purchaser Code]
	,pt.[DOCUMENTSTATE] AS [Approval State]
	,CAST(pt.[ACCOUNTINGDATE] AS date) AS [Accounting Date]
	,pl.[ItemId] AS [PO ITEMID]
	,pl.[VendAccount] AS [Vendor Account]
	,pl.[QTYORDERED]
	,pl.[PURCHSTATUS]
	,pl.[PURCHUNIT]
	,pl.[PURCHASETYPE]
	,pl.[CURRENCYCODE] AS [Currency Code]
	,CAST(pl.[DELIVERYDATE] AS date) AS [Delivery Date]
	,pl.[NAME] AS [PO Line Description]
	,pl.[LINENUMBER] AS [Line Number]
	,pl.[PURCHQTY] AS [PO Quantity]
	,pl.[PURCHPRICE] AS [Unit Price]
	,pl.[TAXGROUP] AS [PO TAXGROUP]
	,pl.[PURCHREQID] AS [Requisition Number]
	,pl.[TAXITEMGROUP] AS [VAT Status]
	,pl.[PROCUREMENTCATEGORY] AS [SupplierCategoryId]

	,pl.[LINEAMOUNT] AS [PO Line Amount]
	,CAST(pl.[REQUESTER] AS nvarchar(10)) + '_' + CAST(pl.[PARTITION] AS NVARCHAR(10)) AS [HcmWorker Key]
	,rescat.[NAME] AS [Procurement Product Category Name]
FROM [synapse_fo].[VENDINVOICEJOUR] vij
	INNER JOIN [synapse_fo].[VENDINVOICETRANS] vit
		ON vij.[PURCHID] = vit.[PURCHID]
		AND vij.[INVOICEID] = vit.[INVOICEID]
		--AND vij.[NUMBERSEQUENCEGROUP] = vit.[NUMBERSEQUENCEGROUP]
		AND vij.[INTERNALINVOICEID] = vit.[INTERNALINVOICEID]
		AND vij.[INVOICEDATE] = vit.[INVOICEDATE]
	INNER JOIN synapse_fo.PURCHLINE pl
		ON vit.ORIGPURCHID = pl.PURCHID
		AND vit.INVENTTRANSID = pl.INVENTTRANSID
	INNER JOIN [synapse_fo].[PURCHTABLE] pt
		ON pl.[PURCHID] = pt.[PURCHID]
	LEFT JOIN [synapse_fo].[ECORESCATEGORY] rescat
		ON pl.[PROCUREMENTCATEGORY] = rescat.[RECID]
		AND pl.[PARTITION] = rescat.[PARTITION]

WHERE vij.[PURCHID] IS NOT NULL
